    <div class="field wide"><label>نوع المخرج المطلوب <em>*</em></label><div class="need-output-grid">${NEED_OUTPUT_TYPES.map(x=>`<button type="button" class="need-output-card ${v.outputType===x[0]?'selected':''}" onclick="needOutputSet('${x[0]}')"><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div></div>
