const DOC_CATEGORIES=['هوية','سيرة ذاتية','مؤهل علمي','شهادة مهنية','ترخيص أو اعتماد','عقد أو تفويض','دليل خبرة','تسليم أو نتيجة','مستند داعم','أخرى'];
const DOC_CONFIDENTIALITY=['عام','مقيد للأعضاء المخولين','سري — مدير المنصة والمتحقق فقط'];
const DOC_RIGHTS=['للتحقق فقط','عرض عام','عرض مقيد','استخدام داخلي فقط'];
const DOC_VERIFY=['جديد','بانتظار التحقق','قيد التحقق','مقبول','مرفوض','منتهي الصلاحية'];
const DOC_CONTENT_LIMIT=350*1024;
function docId(){return'DOC-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,7).toUpperCase()}
function docNorm(d,owner='',field=''){if(typeof d==='string')return{id:docId(),name:d,legacy:true,owner,field,category:'',confidentiality:'مقيد للأعضاء المخولين',rights:'للتحقق فقط',verify:'جديد',versions:[],uploadedAt:new Date().toISOString()};
  d=d||{};d.id=d.id||docId();d.name=d.name||'مستند';d.owner=d.owner||owner;d.field=d.field||field;d.category=d.category||'';d.confidentiality=d.confidentiality||'مقيد للأعضاء المخولين';d.rights=d.rights||'للتحقق فقط';d.verify=d.verify||'جديد';d.versions=Array.isArray(d.versions)?d.versions:[];d.uploadedAt=d.uploadedAt||new Date().toISOString();return d}
function docSize(n){if(!n)return'';return n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB'}
function docLog(action,doc,note=''){G.documentAudit=G.documentAudit||[];G.documentAudit.unshift({at:new Date().toISOString(),actor:typeof G.user==='string'?G.user:'المستخدم',action,docId:doc.id,name:doc.name,note});if(G.documentAudit.length>300)G.documentAudit.length=300}
function readDocumentFile(f,owner,field){return new Promise(resolve=>{let d=docNorm({name:f.name,size:f.size,type:f.type||'',owner,field,uploadedAt:new Date().toISOString(),verify:'جديد'},owner,field);
  if(f.size<=DOC_CONTENT_LIMIT){let r=new FileReader();r.onload=()=>{d.dataUrl=r.result;resolve(d)};r.onerror=()=>resolve(d);r.readAsDataURL(f)}else{d.metadataOnly=true;resolve(d)}})}
function docFieldHtml(type,key,val){let docs=(Array.isArray(val)?val:[]).map(d=>docNorm(d,type,key));G.memberData[type][key]=docs;
  return `<label class="filebox"><input type="file" multiple style="display:none" onchange="mfiles('${enc(type)}','${key}',this)"><b>⭱ رفع عدة مستندات</b><small>يمكن ضبط التصنيف والسرية والحقوق وربط كل مستند بكيان مستقل</small></label>
  <div class="doclist" style="margin-top:10px">${docs.filter(d=>!d.archived).map((d,i)=>docMembershipCard(type,key,d,i)).join('')}</div>`}
function docMembershipCard(type,key,d,i){let exp=d.expiry&&new Date(d.expiry)<new Date().setHours(0,0,0,0);
  return `<div class="doccard"><div class="dochead"><span class="docicon">${IC.doc}</span><span class="docname"><b>${esc(d.name)}</b><small>${esc(d.id)}${d.size?' · '+docSize(d.size):''}${d.legacy?' · سجل قديم محفوظ':''}</small></span><span class="tagb ${exp?'red':d.verify==='مقبول'?'green':d.verify==='مرفوض'?'red':'blue'}">${exp?'منتهي الصلاحية':esc(d.verify)}</span></div>
  <div class="docmeta">
    <label>التصنيف<select class="ctl" onchange="docSet('${enc(type)}','${key}',${i},'category',this.value)"><option value="">اختر…</option>${DOC_CATEGORIES.map(x=>`<option ${d.category===x?'selected':''}>${x}</option>`).join('')}</select></label>
    <label>السرية<select class="ctl" onchange="docSet('${enc(type)}','${key}',${i},'confidentiality',this.value)">${DOC_CONFIDENTIALITY.map(x=>`<option ${d.confidentiality===x?'selected':''}>${x}</option>`).join('')}</select></label>
    <label>حقوق الاستخدام<select class="ctl" onchange="docSet('${enc(type)}','${key}',${i},'rights',this.value)">${DOC_RIGHTS.map(x=>`<option ${d.rights===x?'selected':''}>${x}</option>`).join('')}</select></label>
    <label>انتهاء الصلاحية<input type="date" class="ctl" value="${esc(d.expiry||'')}" onchange="docSet('${enc(type)}','${key}',${i},'expiry',this.value)"></label>
    <label>الجهة المصدرة<input class="ctl" value="${esc(d.issuer||'')}" oninput="docSet('${enc(type)}','${key}',${i},'issuer',this.value,true)"></label>
    <label>رقم الوثيقة<input class="ctl" value="${esc(d.documentNo||'')}" oninput="docSet('${enc(type)}','${key}',${i},'documentNo',this.value,true)"></label>
    <label>تاريخ الإصدار<input type="date" class="ctl" value="${esc(d.issueDate||'')}" onchange="docSet('${enc(type)}','${key}',${i},'issueDate',this.value)"></label>
    <label>الكيان/السجل المرتبط<input class="ctl" value="${esc(d.linkedEntity||'')}" oninput="docSet('${enc(type)}','${key}',${i},'linkedEntity',this.value,true)" placeholder="مؤهل، خبرة، مشروع…"></label>
  </div><div class="docops">
    ${d.dataUrl?`<button class="btn xs soft" onclick="docPreview('${enc(type)}','${key}',${i})">معاينة</button><button class="btn xs soft" onclick="docDownload('${enc(type)}','${key}',${i})">تنزيل</button>`:`<span class="hint">${d.metadataOnly?'حُفظت البيانات الوصفية؛ المحتوى أكبر من حد النموذج التجريبي':'أعد رفع الملف لتفعيل المعاينة والتنزيل'}</span>`}
    <button class="btn xs ghost" onclick="document.getElementById('docrep-${d.id}').click()">استبدال بإصدار جديد</button><input id="docrep-${d.id}" type="file" style="display:none" onchange="docReplace('${enc(type)}','${key}',${i},this)">
    <button class="btn xs danger" onclick="docArchive('${enc(type)}','${key}',${i})">أرشفة</button>
    ${d.versions.length?`<span class="tagb gray">${d.versions.length+1} إصدارات</span>`:''}
  </div></div>`}
function docSet(t,key,i,prop,val,silent){t=dec(t);let docs=G.memberData[t][key]||[],d=docs[i]=docNorm(docs[i],t,key);d[prop]=val;if(!silent)docLog('تحديث بيانات وصفية',d,prop);markMembershipDirty(t);if(!silent)render()}
function docArchive(t,key,i){t=dec(t);let d=docNorm(G.memberData[t][key][i],t,key);if(!confirm('أرشفة المستند «'+d.name+'»؟ سيبقى محفوظًا ويمكن استعادته.'))return;d.archived=true;d.archivedAt=new Date().toISOString();docLog('أرشفة مستند',d);markMembershipDirty(t);render();toast('أُرشف المستند دون حذفه')}
function docReplace(t,key,i,inp){t=dec(t);let f=inp.files[0];if(!f)return;let old=docNorm(G.memberData[t][key][i],t,key);
  readDocumentFile(f,t,key).then(nw=>{nw.id=old.id;nw.category=old.category;nw.confidentiality=old.confidentiality;nw.rights=old.rights;nw.expiry=old.expiry;nw.issuer=old.issuer;nw.documentNo=old.documentNo;nw.issueDate=old.issueDate;nw.linkedEntity=old.linkedEntity;nw.versions=[...(old.versions||[]),{name:old.name,size:old.size,type:old.type,uploadedAt:old.uploadedAt,replacedAt:new Date().toISOString()}];G.memberData[t][key][i]=nw;docLog('استبدال مستند بإصدار جديد',nw,old.name+' ← '+nw.name);markMembershipDirty(t);render();toast('حُفظ الإصدار الجديد مع سجل الإصدارات')})}
function docPreview(t,key,i){t=dec(t);let d=docNorm(G.memberData[t][key][i],t,key);if(!d.dataUrl){toast('لا توجد نسخة محتوى محفوظة للمعاينة');return}let img=(d.type||'').startsWith('image/');
  openModal(`<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px"><b style="flex:1">${esc(d.name)}</b><button class="btn xs ghost" onclick="closeOverlay()">إغلاق</button></div>${img?`<img alt="${esc(d.name)}" src="${d.dataUrl}" style="display:block;max-width:100%;max-height:65vh;margin:auto;border-radius:9px">`:`<iframe sandbox="" title="${esc(d.name)}" src="${d.dataUrl}" style="width:100%;height:65vh;border:0;border-radius:9px;background:#fff"></iframe>`}`)}
function docDownload(t,key,i){t=dec(t);let d=docNorm(G.memberData[t][key][i],t,key);if(!d.dataUrl){toast('لا توجد نسخة محتوى محفوظة للتنزيل');return}let a=document.createElement('a');a.href=d.dataUrl;a.download=d.name;a.click();docLog('تنزيل مستند',d);persist(true)}
function documentRows(){let out=[],types=[...new Set([...Object.keys(G.memberData||{}),...(G.memberships||[])])];
  types.forEach(type=>{let v=G.memberData[type]||{},F=membershipForm(type),fileKeys=new Set([...(F?.fields||[]).filter(f=>f[2]==='file').map(f=>f[0]),'_documentCenter']);fileKeys.forEach(key=>{if(!Array.isArray(v[key]))return;v[key]=v[key].map(d=>docNorm(d,type,key));v[key].forEach((doc,index)=>out.push({type,key,index,doc,source:'membership'}))});
    let defs=MEMBER_REPEATABLE[type]||[],recordMap=G.memberRecords?.[type]||{};defs.forEach(def=>{let fileKeys=def.fields.filter(k=>(F?.fields||[]).find(f=>f[0]===k)?.[2]==='file');(recordMap[def.key]||[]).forEach((row,ri)=>fileKeys.forEach(key=>{if(!Array.isArray(row[key]))return;row[key]=row[key].map(d=>docNorm(d,type,def.key+' / '+key));row[key].forEach((doc,index)=>out.push({type,key,index,doc,source:'record',record:def.key,recordIndex:ri}))}))})});
  let wizardFiles=S.flatMap(s=>s[2]).filter(f=>f[2]==='file').map(f=>f[0]);wizardFiles.forEach(key=>{if(!Array.isArray(W[key]))return;W[key]=W[key].map(d=>docNorm(d,'خبير','الملف المهني / '+key));W[key].forEach((doc,index)=>out.push({type:'خبير',key,index,doc,source:'wizard'}))});
  Object.keys(REC).forEach(recKey=>{let fileKeys=REC[recKey].filter(f=>f[2]==='file').map(f=>f[0]);(W[recKey]||[]).forEach((row,ri)=>fileKeys.forEach(key=>{if(!Array.isArray(row[key]))return;row[key]=row[key].map(d=>docNorm(d,'خبير',recKey+' / '+key));row[key].forEach((doc,index)=>out.push({type:'خبير',key,index,doc,source:'wizardRecord',record:recKey,recordIndex:ri}))}))});
  return out}
function docById(id){return documentRows().find(r=>r.doc.id===id)}
function docSetId(id,prop,val){let r=docById(id);if(!r)return;if(['verify','verificationNote'].includes(prop)&&!isPlatformOperator()){toast('قرار التحقق متاح فقط لمشغل منصة معتمد');return}r.doc[prop]=val;docLog(prop==='verify'?'تحديث حالة تحقق المستند':'تحديث بيانات وصفية',r.doc,prop);markMembershipDirty(r.type);render()}
function docToggleArchiveId(id){let r=docById(id);if(!r)return;r.doc.archived=!r.doc.archived;r.doc.archivedAt=r.doc.archived?new Date().toISOString():null;docLog(r.doc.archived?'أرشفة مستند':'استعادة مستند',r.doc);markMembershipDirty(r.type);render();toast(r.doc.archived?'أُرشف المستند':'استُعيد المستند')}
function docPreviewId(id){let r=docById(id);if(!r||!r.doc.dataUrl){toast('لا توجد نسخة محتوى محفوظة للمعاينة');return}let d=r.doc,img=(d.type||'').startsWith('image/');openModal(`<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px"><b style="flex:1">${esc(d.name)}</b><button class="btn xs ghost" onclick="closeOverlay()">إغلاق</button></div>${img?`<img alt="${esc(d.name)}" src="${d.dataUrl}" style="display:block;max-width:100%;max-height:65vh;margin:auto;border-radius:9px">`:`<iframe sandbox="" title="${esc(d.name)}" src="${d.dataUrl}" style="width:100%;height:65vh;border:0;border-radius:9px;background:#fff"></iframe>`}`)}
function docDownloadId(id){let r=docById(id);if(!r||!r.doc.dataUrl){toast('لا توجد نسخة محتوى محفوظة للتنزيل');return}let a=document.createElement('a');a.href=r.doc.dataUrl;a.download=r.doc.name;a.click();docLog('تنزيل مستند',r.doc);persist(true)}
function docReplaceId(id,inp){let r=docById(id),f=inp.files[0];if(!r||!f)return;let old=r.doc;readDocumentFile(f,old.owner,old.field).then(nw=>{let history=[...(old.versions||[]),{name:old.name,size:old.size,type:old.type,uploadedAt:old.uploadedAt,replacedAt:new Date().toISOString()}];['id','category','confidentiality','rights','expiry','issuer','documentNo','issueDate','linkedEntity','owner','field'].forEach(p=>{if(old[p])nw[p]=old[p]});nw.versions=history;Object.keys(old).forEach(k=>delete old[k]);Object.assign(old,nw);docLog('استبدال مستند بإصدار جديد',old);markMembershipDirty(r.type);render();toast('حُفظ الإصدار الجديد مع سجل الإصدارات')})}
function docGeneralUpload(inp){let type=$('docOwner')?.value||G.activeMembership||(G.memberships||[])[0];if(!type){toast('اختر عضوية أولًا');return}G.memberData[type]=G.memberData[type]||{};let key='_documentCenter',files=[...inp.files];G.memberData[type][key]=G.memberData[type][key]||[];
  Promise.all(files.map(f=>readDocumentFile(f,type,key))).then(docs=>{G.memberData[type][key].push(...docs);docs.forEach(d=>docLog('رفع مستند',d));markMembershipDirty(type);render();toast('أُضيفت المستندات إلى المركز')})}
function rDocumentCenter(){let rows=documentRows(),f=G.docFilters=G.docFilters||{q:'',owner:'',category:'',verify:'',archive:'active'},today=new Date().setHours(0,0,0,0),soon=Date.now()+30*86400000,canVerify=isPlatformOperator();
  let active=rows.filter(r=>!r.doc.archived),expired=active.filter(r=>r.doc.expiry&&new Date(r.doc.expiry)<today).length,expiring=active.filter(r=>r.doc.expiry&&new Date(r.doc.expiry)>=today&&new Date(r.doc.expiry)<=soon).length,pending=active.filter(r=>['جديد','بانتظار التحقق','قيد التحقق'].includes(r.doc.verify)).length;
  let shown=rows.filter(r=>{let d=r.doc,text=[d.name,d.id,d.issuer,d.documentNo,d.linkedEntity,r.type].join(' ');return(!f.q||text.includes(f.q))&&(!f.owner||r.type===f.owner)&&(!f.category||d.category===f.category)&&(!f.verify||d.verify===f.verify)&&(f.archive==='all'||(f.archive==='archived'?d.archived:!d.archived))});
  let cards=shown.map(({type,doc})=>`<div class="doccard ${doc.archived?'archived':''}"><div class="dochead"><span class="docicon">${IC.doc}</span><span class="docname"><b>${esc(doc.name)}</b><small>${esc(doc.id)} · عضوية ${esc(type)}${doc.size?' · '+docSize(doc.size):''}</small></span><span class="tagb ${doc.verify==='مقبول'?'green':doc.verify==='مرفوض'?'red':'blue'}">${esc(doc.verify)}</span>${doc.archived?'<span class="tagb gray">مؤرشف</span>':''}</div>
    <div class="docmeta"><label>التصنيف<select class="ctl" onchange="docSetId('${doc.id}','category',this.value)"><option value="">اختر…</option>${DOC_CATEGORIES.map(x=>`<option ${doc.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>السرية<select class="ctl" onchange="docSetId('${doc.id}','confidentiality',this.value)">${DOC_CONFIDENTIALITY.map(x=>`<option ${doc.confidentiality===x?'selected':''}>${x}</option>`).join('')}</select></label><label>حقوق الاستخدام<select class="ctl" onchange="docSetId('${doc.id}','rights',this.value)">${DOC_RIGHTS.map(x=>`<option ${doc.rights===x?'selected':''}>${x}</option>`).join('')}</select></label><label>حالة التحقق${canVerify?`<select class="ctl" onchange="docSetId('${doc.id}','verify',this.value)">${DOC_VERIFY.map(x=>`<option ${doc.verify===x?'selected':''}>${x}</option>`).join('')}</select>`:`<span class="ctl" style="display:block;background:#f4f6f8">${esc(doc.verify)}</span>`}</label><label>الجهة المصدرة<input class="ctl" value="${esc(doc.issuer||'')}" onchange="docSetId('${doc.id}','issuer',this.value)"></label><label>رقم الوثيقة<input class="ctl" value="${esc(doc.documentNo||'')}" onchange="docSetId('${doc.id}','documentNo',this.value)"></label><label>الكيان المرتبط<input class="ctl" value="${esc(doc.linkedEntity||'')}" onchange="docSetId('${doc.id}','linkedEntity',this.value)"></label><label>انتهاء الصلاحية<input type="date" class="ctl" value="${esc(doc.expiry||'')}" onchange="docSetId('${doc.id}','expiry',this.value)"></label>${canVerify?`<label style="grid-column:1/-1">ملاحظات التحقق<input class="ctl" value="${esc(doc.verificationNote||'')}" onchange="docSetId('${doc.id}','verificationNote',this.value)" placeholder="سبب القبول أو الرفض أو طلب الاستكمال"></label>`:''}</div>
    <div class="docops">${doc.dataUrl?`<button class="btn xs soft" onclick="docPreviewId('${doc.id}')">معاينة</button><button class="btn xs soft" onclick="docDownloadId('${doc.id}')">تنزيل</button>`:''}<button class="btn xs ghost" onclick="document.getElementById('center-rep-${doc.id}').click()">استبدال بإصدار جديد</button><input id="center-rep-${doc.id}" type="file" style="display:none" onchange="docReplaceId('${doc.id}',this)"><button class="btn xs ${doc.archived?'success':'danger'}" onclick="docToggleArchiveId('${doc.id}')">${doc.archived?'استعادة':'أرشفة'}</button>${doc.versions.length?`<span class="tagb gray">${doc.versions.length+1} إصدارات محفوظة</span>`:''}<span class="hint">${esc(doc.rights)} · ${esc(doc.confidentiality)}</span></div></div>`).join('');
  return pagehead(data[54],`<button class="btn ghost sm" onclick="go(11)">مركز الأدلة</button>`)+`
  <div class="grid c4"><div class="card metric blue"><div class="k">المستندات النشطة</div><div class="v">${active.length}</div></div><div class="card metric amber"><div class="k">بانتظار التحقق</div><div class="v">${pending}</div></div><div class="card metric red"><div class="k">منتهية الصلاحية</div><div class="v">${expired}</div></div><div class="card metric gold"><div class="k">تنتهي خلال 30 يومًا</div><div class="v">${expiring}</div></div></div>
  <div class="card panel mt"><h3>إضافة مستندات <span class="line"></span></h3><div class="fields" style="margin-top:12px"><div class="field"><label>العضوية المالكة</label><select id="docOwner" class="ctl">${(G.memberships||[]).map(x=>`<option ${x===G.activeMembership?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>الملفات</label><label class="filebox" style="padding:9px"><input type="file" multiple style="display:none" onchange="docGeneralUpload(this)"><b>⭱ اختيار عدة ملفات</b><small>تُحفظ البيانات الوصفية دائمًا</small></label></div></div></div>
  <div class="card panel mt"><div class="docfilters"><label>البحث<input class="ctl" value="${esc(f.q)}" oninput="G.docFilters.q=this.value;persist(true)" onchange="render()" placeholder="الاسم، الرقم، الجهة، الكيان…"></label><label>العضوية<select class="ctl" onchange="G.docFilters.owner=this.value;persist(true);render()"><option value="">الكل</option>${[...new Set(rows.map(r=>r.type))].map(x=>`<option ${f.owner===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>التصنيف<select class="ctl" onchange="G.docFilters.category=this.value;persist(true);render()"><option value="">الكل</option>${DOC_CATEGORIES.map(x=>`<option ${f.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>التحقق<select class="ctl" onchange="G.docFilters.verify=this.value;persist(true);render()"><option value="">الكل</option>${DOC_VERIFY.map(x=>`<option ${f.verify===x?'selected':''}>${x}</option>`).join('')}</select></label><label>الأرشيف<select class="ctl" onchange="G.docFilters.archive=this.value;persist(true);render()"><option value="active" ${f.archive==='active'?'selected':''}>النشطة</option><option value="archived" ${f.archive==='archived'?'selected':''}>المؤرشفة</option><option value="all" ${f.archive==='all'?'selected':''}>الكل</option></select></label></div></div>
  <div class="doclist mt">${cards||`<div class="card empty"><b>لا توجد مستندات مطابقة</b><p>ارفع مستندًا جديدًا أو عدّل عوامل التصفية.</p></div>`}</div>`}

function membershipCompletion(type,F,v){
  let repeatKeys=new Set((MEMBER_REPEATABLE[type]||[]).flatMap(d=>d.fields)),required=F.fields.filter(f=>f[3]&&!repeatKeys.has(f[0])),filled=required.filter(f=>Array.isArray(v[f[0]])?v[f[0]].length:String(v[f[0]]??'').trim()).length;
  let requiredRecords=(MEMBER_REPEATABLE[type]||[]).filter(d=>d.required),filledRecords=requiredRecords.filter(d=>memberRecords(type,d.key).length).length,total=required.length+requiredRecords.length,done=filled+filledRecords;
  return{done,total,pct:total?Math.round(done*100/total):100}
}
function membershipStepMissing(type,F,v,ms){
  let recordKeys=repeatFieldKeys(type,ms),fields=(F.stepMap[ms]||[]).filter(k=>!recordKeys.has(k)).map(k=>F.fields.find(f=>f[0]===k)).filter(f=>f&&f[3]);
  let missing=fields.filter(f=>!(Array.isArray(v[f[0]])?v[f[0]].length:String(v[f[0]]??'').trim())).map(f=>f[1]);
  repeatAt(type,ms).filter(d=>d.required&&!memberRecords(type,d.key).length).forEach(d=>missing.push('سجل واحد على الأقل: '+d.label));return missing
}
function rMembershipForm(type){let F=membershipForm(type);if(!F)return'';
  let MD=G.memberData=G.memberData||{};let v=MD[type]=MD[type]||{};
  G.memberStep=G.memberStep||{};G.memberPrivacy=G.memberPrivacy||{};G.memberPrivacy[type]=G.memberPrivacy[type]||{};
  let ms=Math.max(0,Math.min(G.memberStep[type]||0,F.steps.length-1));G.memberStep[type]=ms;
  let recordDefs=repeatAt(type,ms),recordKeys=repeatFieldKeys(type,ms);
  let keys=F.stepMap[ms]||[],stepFields=keys.filter(k=>!recordKeys.has(k)).map(k=>F.fields.find(f=>f[0]===k)).filter(Boolean);
  let done=G.completed.includes(type),lm=lifeMeta(type),completion=membershipCompletion(type,F,v),stepMissing=membershipStepMissing(type,F,v,ms);
  let fieldsHtml=stepFields.map(f=>{let[k,l,t,req,src]=f,val=v[k]??'',opts=mlinked(type,k,v,src);
    let wide=t==='multi'||t==='file';let c='';
    if(t==='select')c=`<select class="ctl" onchange="mset('${enc(type)}','${k}',this.value)"><option value="">اختر…</option>${opts.map(o=>`<option ${val===o?'selected':''}>${o}</option>`).join('')}</select>`;
    else if(t==='multi')c=`<div class="chips">${opts.map(o=>`<button type="button" class="chip ${(val||[]).includes(o)?'sel':''}" onclick="mtoggle('${enc(type)}','${k}',dec('${enc(o)}'))">${(val||[]).includes(o)?'✓ ':''}${o}</button>`).join('')}</div>`;
    else if(t==='file')c=docFieldHtml(type,k,val);
    else if(t==='textarea')c=`<textarea class="ctl" rows="4" oninput="mset('${enc(type)}','${k}',this.value)">${esc(val)}</textarea>`;
    else c=`<input class="ctl" type="${t}" ${t==='number'?'min="0" step="1"':''} value="${esc(val)}" oninput="mset('${enc(type)}','${k}',this.value)">`;
    let hidden=G.memberPrivacy[type][k];
    return `<div class="field ${wide?'wide':''}"><label><span>${l} ${req?'<em>*</em>':''}</span><button type="button" class="pv ${hidden?'off':''}" onclick="mprivacy('${enc(type)}','${k}')" title="تحديد ظهور هذا البيان">${hidden?'◉ مخفي':'◎ ظاهر'}</button></label>${c}</div>`}).join('');
  fieldsHtml+=recordDefs.map(def=>mrecords(type,def)).join('');
  return pagehead({ctx:'عضوية '+type,title:'إدخال بيانات '+type,desc:'تُستخدم هذه البيانات لإنشاء ملفك في سياق «'+type+'» وتُحفظ تلقائيًا.'})+`
  <div class="statusband ${lm.state==='approved'?'approved':lm.state==='rejected'||lm.state==='needs_changes'?'rejected':lm.state==='submitted'||lm.state==='under_review'?'pending':'draft'}" style="margin-bottom:16px">
    ${lm.state==='approved'?IC.check:lm.state==='submitted'||lm.state==='under_review'?IC.clock:IC.doc} حالة العضوية: <b>${lm.label}</b>${lm.dirty?' — توجد تعديلات غير مرسلة':''}
    <span style="margin-inline-start:auto;display:flex;gap:7px">${lifecycleActions(type)}</span>
  </div>
  <div class="card formcard" style="min-height:0">
    <div class="fh"><div class="kick">الخطوة ${ms+1} من ${F.steps.length} — عضوية ${type}</div><h2>${F.steps[ms]}</h2><p>تُحفظ المدخلات تلقائيًا، ويمكن العودة إلى أي خطوة دون فقد البيانات.</p></div>
    <div class="form-progress" aria-label="اكتمال البيانات الإلزامية"><div><b>اكتمال البيانات الإلزامية</b><span>${completion.done} من ${completion.total} · ${completion.pct}%</span></div><div class="progress-track"><i style="width:${completion.pct}%"></i></div><small>${stepMissing.length?'المتبقي في هذه الخطوة: '+stepMissing.join('، '):'اكتملت المتطلبات الإلزامية لهذه الخطوة ✓'}</small></div>
    <div class="chips" style="margin-bottom:18px">${F.steps.map((s,i)=>`<button type="button" class="chip ${i===ms?'sel':''}" onclick="mjump('${enc(type)}',${i})">${i+1}. ${s}</button>`).join('')}</div>
    <div class="fields">${fieldsHtml}</div>
    <div class="wizfoot"><button class="btn ghost" onclick="mprev('${enc(type)}')">→ ${ms?'الخطوة السابقة':'أنواع العضويات'}</button><span class="sp"></span>
      ${['مركز تدريب','مدرب','مستشار','باحث / أكاديمي'].includes(type)?`<button class="btn ghost" onclick="previewMembershipPublic('${enc(type)}')">${IC.eye} معاينة الملف العام</button>`:''}
      <button class="btn soft" onclick="persist()">حفظ مسودة</button>
      <button class="btn ${ms===F.steps.length-1?'gold':'primary'}" onclick="mnext('${enc(type)}')">${ms===F.steps.length-1?(done?'تحديث البيانات ✓':'إكمال بيانات العضوية ✓'):'حفظ ومتابعة ←'}</button></div></div>`}
function mset(t,k,v){t=dec(t);let d=G.memberData[t];d[k]=v;
  if(/Domain$/.test(k)){let p=k.replace(/Domain$/,'');d[p+'Specialty']='';d[p+'Phase']='';d[p+'AppliedAreas']=[];markMembershipDirty(t);render();return}
  if(/Specialty$/.test(k)){let p=k.replace(/Specialty$/,'');d[p+'Phase']='';d[p+'AppliedAreas']=[];markMembershipDirty(t);render();return}
  if(/Phase$/.test(k)){let p=k.replace(/Phase$/,'');d[p+'AppliedAreas']=[];markMembershipDirty(t);render();return}
  markMembershipDirty(t)}
function mtoggle(t,k,o){t=dec(t);let a=G.memberData[t][k]||[],sel=a.includes(o);G.memberData[t][k]=sel?a.filter(x=>x!==o):[...a,o];markMembershipDirty(t);render()}
function mfiles(t,k,inp){t=dec(t);let files=[...inp.files],v=G.memberData[t],existing=(Array.isArray(v[k])?v[k]:[]).map(d=>docNorm(d,t,k));
  Promise.all(files.map(f=>readDocumentFile(f,t,k))).then(docs=>{v[k]=[...existing,...docs];docs.forEach(d=>docLog('رفع مستند',d));markMembershipDirty(t);render();toast('أُرفقت الملفات دون حذف المستندات السابقة')})}
function mprivacy(t,k){t=dec(t);G.memberPrivacy=G.memberPrivacy||{};G.memberPrivacy[t]=G.memberPrivacy[t]||{};G.memberPrivacy[t][k]=!G.memberPrivacy[t][k];privacyAudit(t,k,G.memberPrivacy[t][k]);persist(true);render();toast(G.memberPrivacy[t][k]?'أُخفي البيان عن الملف العام':'أصبح البيان ظاهرًا في الملف العام')}
function mstepValid(t,idx){let F=membershipForm(t),v=G.memberData[t]||{},rdefs=repeatAt(t,idx),rkeys=repeatFieldKeys(t,idx);rdefs.forEach(d=>migrateLegacyRecord(t,d));
  let missingRecord=rdefs.find(d=>d.required&&!memberRecords(t,d.key).length);if(missingRecord){toast('أضف سجلًا واحدًا على الأقل في: '+missingRecord.label);return false}
  let fs=(F.stepMap[idx]||[]).filter(k=>!rkeys.has(k)).map(k=>F.fields.find(f=>f[0]===k)).filter(Boolean);
  let missing=fs.find(f=>f[3]&&(!v[f[0]]||(Array.isArray(v[f[0]])&&!v[f[0]].length)));if(missing){toast('أكمل: '+missing[1]);return false}
  let badMail=fs.find(f=>f[2]==='email'&&v[f[0]]&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v[f[0]]));if(badMail){toast('أدخل إيميلًا صحيحًا في: '+badMail[1]);return false}
  let badNum=fs.find(f=>f[2]==='number'&&v[f[0]]&&!/^\d+$/.test(v[f[0]]));if(badNum){toast('أدخل رقمًا صحيحًا في: '+badNum[1]);return false}
  return true}
function mjump(t,i){t=dec(t);G.memberStep=G.memberStep||{};G.memberStep[t]=i;persist(true);render();window.scrollTo({top:0})}
function mprev(t){t=dec(t);let i=G.memberStep[t]||0;if(i===0){go(44);return}mback(enc(t))}
function mback(t){t=dec(t);G.memberStep[t]=Math.max(0,(G.memberStep[t]||0)-1);persist(true);render();window.scrollTo({top:0})}
function mnext(t){t=dec(t);let F=membershipForm(t),i=G.memberStep[t]||0;if(!mstepValid(t,i))return;
  if(i<F.steps.length-1){G.memberStep[t]=i+1;G.membershipStatus[t]='قيد الإدخال';persist(true);render();window.scrollTo({top:0});return}
  finishMembership(enc(t))}
function finishMembership(t){t=dec(t);let F=membershipForm(t);let v=G.memberData[t]||{};
  let defs=MEMBER_REPEATABLE[t]||[],allRecordKeys=new Set(defs.flatMap(d=>d.fields));defs.forEach(d=>migrateLegacyRecord(t,d));
  let missingRecord=defs.find(d=>d.required&&!memberRecords(t,d.key).length);if(missingRecord){toast('أضف سجلًا واحدًا على الأقل في: '+missingRecord.label);return}
  let missing=F.fields.filter(f=>!allRecordKeys.has(f[0])&&f[3]&&!String(v[f[0]]||'').trim()&&!(Array.isArray(v[f[0]])&&v[f[0]].length));
  if(missing.length){toast('أكمل: '+missing[0][1]);return}
  if(!G.completed.includes(t))G.completed.push(t);
  G.activeMembership=t;let L=ensureLife(t);
  if(['not_started','needs_changes','rejected','expired'].includes(L.state)){
    L.state='draft';L.dirty=true;L.history.push({state:'draft',at:Date.now(),actor:'صاحب العضوية',note:'استكمال إدخال بيانات العضوية'});G.membershipStatus[t]=LIFE_STATES.draft.label
  }
  if(L.state==='draft')lifeTransition(t,'data_complete','صاحب العضوية','اكتملت جميع البيانات الإلزامية');
  else if(L.state==='data_complete'){L.dirty=false;L.updatedAt=Date.now();G.membershipStatus[t]=LIFE_STATES.data_complete.label}
  G.memberships=[...new Set([...G.memberships,t])];
  syncUnifiedEntity(t);
  let next=G.memberships.find(r=>!G.completed.includes(r));
  persist(true);
  if(next){G.activeMembership=next;if(ensureLife(next).state==='not_started')lifeTransition(next,'draft','المستخدم','بدء إدخال بيانات العضوية');persist(true);go(MEMBER_SCREENS[next]);toast('اكتملت بيانات «'+t+'» — تابع إدخال بيانات «'+next+'»')}
  else{G.ctx=t==='العميل'?'عميل':t;go(2);toast('اكتملت بيانات العضويات المختارة — مرحبًا بك في مساحة العمل 🎉')}}
/* =========================================================
   EIM 6.4 — البحث والنشر والفعاليات وإدارة المعرفة
   سجل موحد: مشروع بحثي ← مخرج منشور ← فعالية ← أصل معرفي
   ========================================================= */
const KNOWLEDGE_TYPES={
  research:{label:'مشروع بحثي',list:'researchProjects',prefix:'RES'},
  publication:{label:'منشور',list:'publications',prefix:'PUB'},
  event:{label:'فعالية',list:'events',prefix:'EVT'},
  asset:{label:'أصل معرفي',list:'assets',prefix:'KNO'},
  lesson:{label:'درس مستفاد',list:'lessons',prefix:'LES'}
};
const PUBLICATION_TYPES=['مقالة بحثية أصلية','مقالة مراجعة','تقرير حالة أو دراسة حالة','اتصال قصير أو ملاحظة موجزة','ورقة منهجية أو تقنية','مقالة منظورية أو تعليق','ورقة مؤتمر','رسالة علمية أو أطروحة','فصل كتاب أو كتاب محرر','نوع حديث أو متخصص'];
const EVENT_TYPES=['مؤتمر','ندوة','حلقة نقاش','ورشة معرفية','ملتقى خبراء','عرض بحثي','مجتمع ممارسة'];
const KNOWLEDGE_ASSET_TYPES=['دليل إجرائي','حالة تطبيقية','درس مستفاد','قالب أو أداة','تقرير فني','مجموعة بيانات','تسجيل معرفي','سؤال وجواب خبير'];
function knowledgeId(prefix){return `${prefix}-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`}
function knowledgeOwner(){return G.user||'شبكة الخبراء العرب'}
function migrateKnowledge(){
  let k=G.knowledge=G.knowledge||{};['researchProjects','publications','events','assets','lessons','registrations'].forEach(x=>k[x]=Array.isArray(k[x])?k[x]:[]);
  k.filters=k.filters||{q:'',type:'all',status:'all'};k.draft=k.draft||null;k.activeId=k.activeId||'';
  if(!k.researchProjects.length)k.researchProjects.push(
    {id:'RES-2026-001',title:'جاهزية المؤسسات العربية لتطبيق الذكاء الاصطناعي',domain:'التقنيات الرقمية والذكاء الاصطناعي',lead:'د. ليلى النعيمي',partners:['مركز الابتكار المؤسسي'],status:'قيد التنفيذ',visibility:'عام',start:'2026-03-01',end:'2026-11-30',abstract:'دراسة تطبيقية لقياس الجاهزية المؤسسية وبناء خارطة انتقال قابلة للتنفيذ.',outputs:['PUB-2026-001'],createdAt:Date.now()-86400000*40}
  );
  if(!k.publications.length)k.publications.push(
    {id:'PUB-2026-001',title:'إطار قياس الجاهزية المؤسسية للذكاء الاصطناعي',publicationType:'ورقة منهجية أو تقنية',authors:['د. ليلى النعيمي','م. سامر الخطيب'],domain:'التقنيات الرقمية والذكاء الاصطناعي',language:'العربية',publishedAt:'2026-06-12',publisher:'شبكة الخبراء العرب',doi:'',license:'CC BY-NC 4.0',peerReview:'محكّم',status:'منشور',visibility:'عام',downloads:184,projectId:'RES-2026-001',summary:'إطار عملي متعدد الأبعاد لتقييم الجاهزية وتحديد أولويات التحول.',createdAt:Date.now()-86400000*25}
  );
  if(!k.events.length)k.events.push(
    {id:'EVT-2026-001',title:'ملتقى الخبراء: الذكاء الاصطناعي في إدارة المشاريع',eventType:'ملتقى خبراء',domain:'التقنيات الرقمية والذكاء الاصطناعي',start:'2026-09-18T09:00',end:'2026-09-18T14:00',mode:'هجين',country:'سلطنة عُمان',venue:'مسقط / عبر المنصة',capacity:150,status:'مفتوح للتسجيل',visibility:'عام',organizer:'شبكة الخبراء العرب',speakers:['د. ليلى النعيمي'],createdAt:Date.now()-86400000*5}
  );
  if(!k.assets.length)k.assets.push(
    {id:'KNO-2026-001',title:'قالب استخلاص الدروس المستفادة من المشاريع',assetType:'قالب أو أداة',domain:'إدارة المشاريع والبرامج',owner:'مكتب إدارة المعرفة',version:'1.0',status:'معتمد',visibility:'للأعضاء',reviewDate:'2027-01-15',tags:['دروس مستفادة','مشاريع'],summary:'قالب موحد لتسجيل السياق والقرار والنتيجة والتوصية وإعادة الاستخدام.',createdAt:Date.now()-86400000*20}
  );
}
function knowledgeAll(){
  migrateKnowledge();let k=G.knowledge;
  return[
    ...k.researchProjects.map(x=>({...x,kind:'research'})),
    ...k.publications.map(x=>({...x,kind:'publication'})),
    ...k.events.map(x=>({...x,kind:'event'})),
    ...k.assets.map(x=>({...x,kind:'asset'})),
    ...k.lessons.map(x=>({...x,kind:'lesson'}))
  ]
}
function knowledgeFind(id){return knowledgeAll().find(x=>x.id===id)}
function knowledgeCanManage(){return !!G.user&&['مدير / مشغل المنصة','باحث / أكاديمي','خبير مستقل','مدرب','مركز تدريب'].includes(G.ctx)}
function knowledgeNew(kind){
  let meta=KNOWLEDGE_TYPES[kind];if(!meta)return;
  G.knowledge.draft={kind,id:'',title:'',status:'مسودة',visibility:'خاص',domain:'',owner:knowledgeOwner(),createdAt:Date.now()};
  persist(true);go(104)
}
function knowledgeEdit(id){let row=knowledgeFind(id);if(!row)return;if(!knowledgeCanManage()){G.knowledge.activeId=id;persist(true);toast('السجل متاح للقراءة؛ يلزم حساب عضو لإدارة المحتوى');return}G.knowledge.draft=JSON.parse(JSON.stringify(row));persist(true);go(104)}
function knowledgeDraftSet(key,value){if(!G.knowledge.draft)return;G.knowledge.draft[key]=value;persist(true)}
function knowledgeSave(publish=false){
  let d=G.knowledge.draft;if(!d)return;
  if(!String(d.title||'').trim()||!String(d.domain||'').trim()){toast('أكمل العنوان والمجال قبل الحفظ');return}
  let meta=KNOWLEDGE_TYPES[d.kind],list=G.knowledge[meta.list],row={...d};
  row.id=row.id||knowledgeId(meta.prefix);row.updatedAt=Date.now();row.status=publish?(d.kind==='event'?'مفتوح للتسجيل':d.kind==='publication'?'منشور':'معتمد'):(row.status||'مسودة');
  let i=list.findIndex(x=>x.id===row.id);if(i>=0)list[i]=row;else list.unshift(row);
  G.knowledge.draft=null;G.knowledge.activeId=row.id;
  if(G.platformAdmin?.adminAudit)G.platformAdmin.adminAudit.unshift({eventId:knowledgeId('AUD'),domain:'المحتوى',action:i>=0?'تحديث سجل معرفي':'إنشاء سجل معرفي',actor:knowledgeOwner(),ref:row.id,risk:'منخفض',outcome:'ناجح',details:row.title,at:Date.now()});
  persist(true);go(row.kind==='event'?102:row.kind==='publication'?101:row.kind==='research'?100:103);toast('حُفظ السجل بنجاح')
}
function knowledgeRegister(id){
  migrateKnowledge();if(!G.user){go(65);toast('سجّل الدخول لإكمال التسجيل');return}
  if(G.knowledge.registrations.some(x=>x.eventId===id&&x.user===G.user)){toast('أنت مسجل في هذه الفعالية');return}
  G.knowledge.registrations.push({registrationId:knowledgeId('REG'),eventId:id,user:G.user,status:'مؤكد',registeredAt:Date.now()});persist(true);render();toast('تم التسجيل في الفعالية')
}
function knowledgeStatusClass(s){return /منشور|معتمد|مفتوح|مكتمل/.test(s||'')?'green':/مسودة|مراجعة|تنفيذ/.test(s||'')?'amber':'gray'}
function knowledgeHead(title,desc,actions=''){return pagehead({ctx:'المعرفة والبحث',title,desc},actions)}
function rKnowledgePublic(){
  migrateKnowledge();let k=G.knowledge,up=k.events.filter(x=>x.status==='مفتوح للتسجيل'),featured=k.publications.filter(x=>x.visibility==='عام'),assets=k.assets.filter(x=>x.visibility!=='خاص');
  return knowledgeHead('بوابة المعرفة والفعاليات','ابحث في البحوث والمنشورات والفعاليات والأدلة المهنية الموثوقة.',knowledgeCanManage()?'<button class="btn primary sm" onclick="go(100)">مساحة الإدارة</button>':'')+`
  <section class="knowledge-hero"><div><span class="kick">ARAB EXPERTS KNOWLEDGE</span><h2>معرفة عربية قابلة للاكتشاف وإعادة الاستخدام</h2><p>يربط السجل الموحد بين المشروع البحثي ومخرجاته ومؤلفيه وفعالياته وأصوله المعرفية.</p><div class="knowledge-search"><input class="ctl" placeholder="ابحث بعنوان أو مجال أو مؤلف…" oninput="G.knowledge.filters.q=this.value;persist(true)" value="${esc(k.filters.q||'')}"><button class="btn primary" onclick="render()">بحث</button></div></div><div class="knowledge-orbit"><b>${k.publications.length+k.assets.length}</b><span>أصل معرفي</span><small>${k.researchProjects.length} أبحاث · ${up.length} فعاليات قادمة</small></div></section>
  <div class="grid c4">${securityMetric('المشاريع البحثية',k.researchProjects.length,'blue')}${securityMetric('المنشورات',k.publications.length,'gold')}${securityMetric('الفعاليات القادمة',up.length,'green')}${securityMetric('الأدلة والأدوات',k.assets.length,'violet')}</div>
  <div class="grid c2 mt"><section class="card panel"><div class="casehead"><h3>منشورات مختارة</h3><button class="btn xs ghost" onclick="go(101)">عرض الكل</button></div>${featured.slice(0,4).map(x=>`<button class="knowledge-item" onclick="knowledgeEdit('${x.id}')"><span class="knowledge-type">منشور</span><b>${esc(x.title)}</b><small>${esc((x.authors||[]).join('، '))} · ${esc(x.publicationType)}</small></button>`).join('')||'<div class="empty">لا توجد منشورات عامة.</div>'}</section>
  <section class="card panel"><div class="casehead"><h3>فعاليات قادمة</h3><button class="btn xs ghost" onclick="go(102)">التقويم</button></div>${up.slice(0,4).map(x=>`<div class="event-row"><time>${esc((x.start||'').slice(0,10))}</time><div><b>${esc(x.title)}</b><small>${esc(x.mode)} · ${esc(x.country)}</small></div><button class="btn xs soft" onclick="knowledgeRegister('${x.id}')">تسجيل</button></div>`).join('')||'<div class="empty">لا توجد فعاليات مفتوحة.</div>'}</section></div>
  <section class="card panel mt"><div class="casehead"><h3>مكتبة الأدلة والأدوات</h3><button class="btn xs ghost" onclick="go(103)">فتح المكتبة</button></div><div class="knowledge-cards">${assets.slice(0,6).map(x=>`<article><span>${esc(x.assetType)}</span><h4>${esc(x.title)}</h4><p>${esc(x.summary||'')}</p><small>الإصدار ${esc(x.version||'1.0')} · ${esc(x.visibility)}</small></article>`).join('')}</div></section>`}
function rResearchRegistry(){
  migrateKnowledge();let rows=G.knowledge.researchProjects;
  return knowledgeHead('سجل المشاريع البحثية','إدارة المبادرة والشركاء والمنهجية والمخرجات وربطها بالمنشورات والأدلة.',`<button class="btn primary sm" onclick="knowledgeNew('research')">مشروع بحثي جديد</button>`)+
  knowledgeTable(rows,'research',['المشروع','القائد والشركاء','الفترة','الحالة','الإتاحة'])
}
function rPublicationRepository(){
  migrateKnowledge();let rows=G.knowledge.publications;
  return knowledgeHead('المستودع البحثي والنشر','سجل موحد للمؤلفين والتحكيم والحقوق والإصدارات والربط بالمشروع البحثي.',knowledgeCanManage()?`<button class="btn primary sm" onclick="knowledgeNew('publication')">إضافة منشور</button>`:'')+
  knowledgeTable(rows,'publication',['المنشور','النوع والمؤلفون','الناشر والتاريخ','الحالة','الإتاحة'])
}
function rEventsCalendar(){
  migrateKnowledge();let rows=G.knowledge.events;
  return knowledgeHead('الفعاليات والمجتمعات المهنية','تقويم موحد للمؤتمرات والندوات والورش ومجتمعات الممارسة مع التسجيل والحضور.',knowledgeCanManage()?`<button class="btn primary sm" onclick="knowledgeNew('event')">إنشاء فعالية</button>`:'')+
  knowledgeTable(rows,'event',['الفعالية','النوع والمجال','التاريخ والمكان','الحالة','السعة'])
}
function rKnowledgeLibrary(){
  migrateKnowledge();let rows=[...G.knowledge.assets,...G.knowledge.lessons];
  return knowledgeHead('مكتبة المعرفة المؤسسية','أدلة ودروس وقوالب وبيانات محكومة بالإصدار والمالك والمراجعة وحقوق الاستخدام.',`<button class="btn primary sm" onclick="knowledgeNew('asset')">إضافة أصل معرفي</button>`)+
  knowledgeTable(rows,'asset',['الأصل المعرفي','النوع والمجال','المالك والإصدار','الحالة','المراجعة'])
}
function knowledgeTable(rows,kind,heads){
  let q=(G.knowledge.filters.q||'').trim().toLowerCase(),filtered=rows.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));
  return `<div class="card filterbar"><input class="ctl" placeholder="تصفية السجل…" value="${esc(G.knowledge.filters.q||'')}" oninput="G.knowledge.filters.q=this.value;persist(true)" onchange="render()"><span class="sp"></span><span class="tagb blue">${filtered.length} سجل</span></div>
  <div class="card panel"><div class="tablewrap"><table class="tbl"><thead><tr><th>الرقم</th>${heads.map(x=>`<th>${x}</th>`).join('')}<th></th></tr></thead><tbody>${filtered.map((x,i)=>knowledgeRow(x,kind,i)).join('')||`<tr><td colspan="${heads.length+2}">لا توجد سجلات مطابقة.</td></tr>`}</tbody></table></div></div>`}
function knowledgeRow(x,kind,i){
  if(kind==='research')return`<tr><td>${i+1}</td><td><b>${esc(x.title)}</b><small>${esc(x.id)} · ${esc(x.domain)}</small></td><td>${esc(x.lead||x.owner)}<small>${esc((x.partners||[]).join('، '))}</small></td><td>${esc(x.start||'—')}<small>${esc(x.end||'')}</small></td><td><span class="tagb ${knowledgeStatusClass(x.status)}">${esc(x.status)}</span></td><td>${esc(x.visibility)}</td><td><button class="btn xs ghost" onclick="knowledgeEdit('${x.id}')">فتح</button></td></tr>`;
  if(kind==='publication')return`<tr><td>${i+1}</td><td><b>${esc(x.title)}</b><small>${esc(x.id)} · ${esc(x.domain)}</small></td><td>${esc(x.publicationType)}<small>${esc((x.authors||[]).join('، '))}</small></td><td>${esc(x.publisher||'—')}<small>${esc(x.publishedAt||'')}</small></td><td><span class="tagb ${knowledgeStatusClass(x.status)}">${esc(x.status)}</span></td><td>${esc(x.visibility)}</td><td><button class="btn xs ghost" onclick="knowledgeEdit('${x.id}')">فتح</button></td></tr>`;
  if(kind==='event')return`<tr><td>${i+1}</td><td><b>${esc(x.title)}</b><small>${esc(x.id)} · ${esc(x.organizer)}</small></td><td>${esc(x.eventType)}<small>${esc(x.domain)}</small></td><td>${esc((x.start||'').replace('T',' '))}<small>${esc(x.mode)} · ${esc(x.venue||x.country)}</small></td><td><span class="tagb ${knowledgeStatusClass(x.status)}">${esc(x.status)}</span></td><td>${Number(x.capacity||0)}</td><td>${x.status==='مفتوح للتسجيل'?`<button class="btn xs soft" onclick="knowledgeRegister('${x.id}')">تسجيل</button>`:''}<button class="btn xs ghost" onclick="knowledgeEdit('${x.id}')">فتح</button></td></tr>`;
  return`<tr><td>${i+1}</td><td><b>${esc(x.title)}</b><small>${esc(x.id)} · ${esc(x.summary||'')}</small></td><td>${esc(x.assetType||'درس مستفاد')}<small>${esc(x.domain)}</small></td><td>${esc(x.owner)}<small>الإصدار ${esc(x.version||'1.0')}</small></td><td><span class="tagb ${knowledgeStatusClass(x.status)}">${esc(x.status)}</span></td><td>${esc(x.reviewDate||'—')}</td><td><button class="btn xs ghost" onclick="knowledgeEdit('${x.id}')">فتح</button></td></tr>`
}
function knowledgeOptions(list,value){return list.map(x=>`<option ${value===x?'selected':''}>${esc(x)}</option>`).join('')}
function rKnowledgeEditor(){
  migrateKnowledge();let d=G.knowledge.draft;if(!d)return knowledgeHead('محرر المعرفة','لم يُحدد سجل للتحرير.')+'<div class="empty">اختر سجلًا أو أنشئ سجلًا جديدًا.</div>';
  let typeOptions=d.kind==='publication'?PUBLICATION_TYPES:d.kind==='event'?EVENT_TYPES:d.kind==='asset'?KNOWLEDGE_ASSET_TYPES:[];
  return knowledgeHead(d.id?'تعديل '+KNOWLEDGE_TYPES[d.kind].label:'إنشاء '+KNOWLEDGE_TYPES[d.kind].label,'احفظ المسودة أو أرسلها للنشر وفق صلاحيات الدور وسياسة الإتاحة.')+`
  <div class="card formcard knowledge-editor"><div class="fields">
  <div class="field wide"><label>العنوان <em>*</em></label><input class="ctl" value="${esc(d.title||'')}" oninput="knowledgeDraftSet('title',this.value)"></div>
  <div class="field"><label>المجال <em>*</em></label><select class="ctl" onchange="knowledgeDraftSet('domain',this.value)"><option value="">اختر المجال</option>${Object.keys(TAX).map(x=>`<option ${d.domain===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>
  ${typeOptions.length?`<div class="field"><label>${d.kind==='event'?'نوع الفعالية':d.kind==='publication'?'نوع المنشور':'نوع الأصل'}</label><select class="ctl" onchange="knowledgeDraftSet('${d.kind==='event'?'eventType':d.kind==='publication'?'publicationType':'assetType'}',this.value)"><option value="">اختر</option>${knowledgeOptions(typeOptions,d.eventType||d.publicationType||d.assetType)}</select></div>`:''}
  ${d.kind==='research'?`<div class="field"><label>قائد البحث</label><input class="ctl" value="${esc(d.lead||'')}" oninput="knowledgeDraftSet('lead',this.value)"></div><div class="field"><label>تاريخ البداية</label><input type="date" class="ctl" value="${esc(d.start||'')}" onchange="knowledgeDraftSet('start',this.value)"></div><div class="field"><label>تاريخ النهاية</label><input type="date" class="ctl" value="${esc(d.end||'')}" onchange="knowledgeDraftSet('end',this.value)"></div>`:''}
  ${d.kind==='publication'?`<div class="field wide"><label>المؤلفون (افصل بينهم بفاصلة)</label><input class="ctl" value="${esc((d.authors||[]).join('، '))}" oninput="knowledgeDraftSet('authors',this.value.split(/[,،]/).map(x=>x.trim()).filter(Boolean))"></div><div class="field"><label>الناشر</label><input class="ctl" value="${esc(d.publisher||'')}" oninput="knowledgeDraftSet('publisher',this.value)"></div><div class="field"><label>تاريخ النشر</label><input type="date" class="ctl" value="${esc(d.publishedAt||'')}" onchange="knowledgeDraftSet('publishedAt',this.value)"></div><div class="field"><label>التحكيم</label><select class="ctl" onchange="knowledgeDraftSet('peerReview',this.value)">${knowledgeOptions(['غير محكّم','مراجعة داخلية','محكّم'],d.peerReview)}</select></div><div class="field"><label>ترخيص الاستخدام</label><input class="ctl" value="${esc(d.license||'')}" oninput="knowledgeDraftSet('license',this.value)"></div>`:''}
  ${d.kind==='event'?`<div class="field"><label>البداية</label><input type="datetime-local" class="ctl" value="${esc(d.start||'')}" onchange="knowledgeDraftSet('start',this.value)"></div><div class="field"><label>النهاية</label><input type="datetime-local" class="ctl" value="${esc(d.end||'')}" onchange="knowledgeDraftSet('end',this.value)"></div><div class="field"><label>نمط التقديم</label><select class="ctl" onchange="knowledgeDraftSet('mode',this.value)">${knowledgeOptions(['حضوري','عن بعد','هجين'],d.mode)}</select></div><div class="field"><label>الدولة</label><select class="ctl" onchange="knowledgeDraftSet('country',this.value)"><option value="">اختر</option>${countries.map(x=>`<option ${d.country===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>المكان أو الرابط</label><input class="ctl" value="${esc(d.venue||'')}" oninput="knowledgeDraftSet('venue',this.value)"></div><div class="field"><label>الطاقة الاستيعابية</label><input type="number" min="1" step="1" class="ctl" value="${esc(d.capacity||'')}" oninput="knowledgeDraftSet('capacity',this.value)"></div>`:''}
  ${d.kind==='asset'?`<div class="field"><label>المالك المعرفي</label><input class="ctl" value="${esc(d.owner||'')}" oninput="knowledgeDraftSet('owner',this.value)"></div><div class="field"><label>الإصدار</label><input class="ctl" value="${esc(d.version||'1.0')}" oninput="knowledgeDraftSet('version',this.value)"></div><div class="field"><label>تاريخ المراجعة</label><input type="date" class="ctl" value="${esc(d.reviewDate||'')}" onchange="knowledgeDraftSet('reviewDate',this.value)"></div>`:''}
  <div class="field"><label>صلاحية العرض</label><select class="ctl" onchange="knowledgeDraftSet('visibility',this.value)">${knowledgeOptions(['عام','للأعضاء','خاص'],d.visibility)}</select></div>
  <div class="field wide"><label>الملخص</label><textarea class="ctl" rows="5" oninput="knowledgeDraftSet('${d.kind==='research'?'abstract':'summary'}',this.value)">${esc(d.abstract||d.summary||'')}</textarea></div>
  <div class="field wide"><label>المرفقات</label><label class="filebox"><input type="file" multiple style="display:none" onchange="knowledgeDraftSet('files',[...this.files].map(x=>x.name));render()"><b>رفع عدة مستندات</b><small>${esc((d.files||[]).join('، ')||'PDF، Word، صور، بيانات')}</small></label></div>
  </div><div class="wizfoot"><button class="btn ghost" onclick="goBack()">الصفحة السابقة</button><span class="sp"></span><button class="btn soft" onclick="knowledgeSave(false)">حفظ مسودة</button><button class="btn primary" onclick="knowledgeSave(true)">حفظ وإرسال للنشر</button></div></div>`}
/* =========================================================
   EIM 6.4 — الحوكمة والصلاحيات والخصوصية والتكاملات
   تستكمل ولا تكرر: المشغلون 95، التدقيق 96، القضايا 97، السياسات 98
   ========================================================= */
const GOV_ROLES=['زائر','عضو مهني','باحث / أكاديمي','مركز تدريب','عميل','متحقق','مشغل المنصة','مدير المنصة'];
const GOV_PERMISSIONS=[
  ['public.read','عرض المحتوى العام','الموقع العام'],
  ['profile.manage','إدارة الملف والعضويات','العضويات'],
  ['knowledge.contribute','إضافة أصل معرفي','المعرفة'],
  ['research.manage','إدارة مشروع بحثي','المعرفة'],
  ['publication.submit','إرسال منشور للمراجعة','المعرفة'],
  ['publication.approve','اعتماد النشر','المعرفة'],
  ['event.manage','إنشاء وإدارة فعالية','الفعاليات'],
  ['client.need.manage','إدارة احتياجات العميل','العملاء'],
  ['matching.run','تشغيل المطابقة','المطابقة'],
  ['verification.decide','إصدار قرار تحقق','التحقق'],
  ['privacy.self.manage','إدارة خصوصية بياناته','الخصوصية'],
  ['privacy.override','عرض البيانات المقيدة بأمر نظامي','الخصوصية'],
  ['audit.read','قراءة سجل التدقيق','التدقيق'],
  ['audit.case.manage','إدارة قضايا التدقيق','التدقيق'],
  ['role.grant','منح الأدوار والصلاحيات','الحوكمة'],
  ['integration.manage','إدارة التكاملات','التكاملات']
];
const GOV_ROLE_DEFAULTS={
  'زائر':['public.read'],
  'عضو مهني':['public.read','profile.manage','knowledge.contribute','publication.submit','event.manage','privacy.self.manage'],
  'باحث / أكاديمي':['public.read','profile.manage','knowledge.contribute','research.manage','publication.submit','event.manage','privacy.self.manage'],
  'مركز تدريب':['public.read','profile.manage','knowledge.contribute','event.manage','privacy.self.manage'],
  'عميل':['public.read','profile.manage','client.need.manage','matching.run','privacy.self.manage'],
  'متحقق':['public.read','verification.decide','privacy.self.manage'],
  'مشغل المنصة':['public.read','publication.approve','audit.read','audit.case.manage','integration.manage','privacy.self.manage'],
  'مدير المنصة':GOV_PERMISSIONS.map(x=>x[0])
};
function governanceId(prefix){return `${prefix}-${String(Date.now()).slice(-9)}`}
function migrateGovernance(){
  let g=G.governance=G.governance||{};
  ['roles','permissions','grants','accessReviews','privacyPolicies','consents','integrations','syncRuns','changes'].forEach(x=>g[x]=Array.isArray(g[x])?g[x]:[]);
  if(!g.permissions.length)g.permissions=GOV_PERMISSIONS.map((x,i)=>({permissionId:x[0],name:x[1],domain:x[2],risk:/override|grant|approve|decide|integration/.test(x[0])?'مرتفع':'عادي',sort:i}));
  if(!g.roles.length)g.roles=GOV_ROLES.map((name,i)=>({roleId:`ROLE-${String(i+1).padStart(2,'0')}`,name,system:true,status:'نشط'}));
  if(!g.grants.length)Object.entries(GOV_ROLE_DEFAULTS).forEach(([role,perms])=>perms.forEach(permissionId=>g.grants.push({role,permissionId,source:'خط الأساس',grantedAt:Date.now()})));
  if(!g.privacyPolicies.length)g.privacyPolicies=[
    {policyId:'PRI-001',name:'إظهار المعلومات المسموحة فقط',scope:'الملفات العامة',retention:'مدة العضوية + 5 سنوات',legalBasis:'موافقة المستخدم وتنفيذ العقد',status:'نافذة',version:'1.0'},
    {policyId:'PRI-002',name:'البيانات المخفية لمدير المنصة فقط',scope:'التحقق والنزاعات',retention:'7 سنوات',legalBasis:'المصلحة المشروعة والامتثال',status:'نافذة',version:'1.0'}
  ];
  if(!g.integrations.length)g.integrations=[
    {integrationId:'INT-IDENTITY',name:'الهوية والتحقق',category:'هوية',direction:'ثنائي',status:'غير متصل',environment:'تجريبي',data:['معرف المستخدم','حالة التحقق'],lastSync:'',owner:'مسؤول الأمن'},
    {integrationId:'INT-PAYMENT',name:'بوابة الدفع',category:'مالية',direction:'صادر ووارد',status:'غير متصل',environment:'تجريبي',data:['الفاتورة','حالة الدفع','الاسترداد'],lastSync:'',owner:'الإدارة المالية'},
    {integrationId:'INT-MAIL',name:'البريد والإشعارات',category:'اتصال',direction:'صادر',status:'متصل',environment:'تجريبي',data:['الإيميل','قالب الرسالة'],lastSync:new Date().toISOString(),owner:'مشغل المنصة'},
    {integrationId:'INT-SEARCH',name:'فهرس البحث',category:'بحث',direction:'صادر',status:'متصل',environment:'تجريبي',data:['الملفات العامة','الدورات','المعرفة'],lastSync:new Date().toISOString(),owner:'مسؤول البيانات'}
  ];
  g.activeRole=g.activeRole||'عضو مهني';g.integrationDraft=g.integrationDraft||null;
}
function governanceIsAdmin(){return G.user&&G.ctx==='مدير / مشغل المنصة'}
function roleHas(role,permissionId){migrateGovernance();return G.governance.grants.some(x=>x.role===role&&x.permissionId===permissionId)}
function governanceChange(action,ref,details,risk='عادي'){
  let x={changeId:governanceId('CHG'),action,ref,details,risk,actor:G.user||'النظام',at:Date.now()};
  G.governance.changes.unshift(x);
  if(G.platformAdmin?.adminAudit)G.platformAdmin.adminAudit.unshift({eventId:x.changeId,domain:'الحوكمة',action,actor:x.actor,ref,risk:risk==='عالي'?'مرتفع':'منخفض',outcome:'ناجح',details,at:x.at})
}
function permissionToggle(role,permissionId){
  role=dec(role);
  if(!governanceIsAdmin()){toast('هذه العملية متاحة لمدير المنصة فقط');return}
  if(role==='مدير المنصة'&&permissionId==='role.grant'){toast('لا يمكن إزالة صلاحية إدارة الأدوار من مدير المنصة الأساسي');return}
  let i=G.governance.grants.findIndex(x=>x.role===role&&x.permissionId===permissionId);
  if(i>=0)G.governance.grants.splice(i,1);else G.governance.grants.push({role,permissionId,source:'تعديل إداري',grantedAt:Date.now(),grantedBy:G.user});
  governanceChange(i>=0?'سحب صلاحية':'منح صلاحية',role,permissionId,'عالي');persist(true);render();toast('حُفظ التغيير في سجل الحوكمة')
}
function privacyStats(){
  let all=0,hidden=0;
  Object.values(G.memberPrivacy||{}).forEach(o=>Object.values(o||{}).forEach(v=>{all++;if(v)hidden++}));
  Object.values(G.memberRecordPrivacy||{}).forEach(o=>Object.values(o||{}).forEach(v=>{all++;if(v)hidden++}));
  Object.values(W._private||{}).forEach(v=>{all++;if(v)hidden++});
  return{all,hidden,public:Math.max(0,all-hidden),score:all?Math.round((all-hidden)/all*100):100}
}
function privacyConsent(action){
  migrateGovernance();let existing=G.governance.consents.find(x=>x.user===(G.user||'زائر')&&x.purpose==='النشر العام');
  if(existing){existing.status=action;existing.updatedAt=Date.now()}else G.governance.consents.unshift({consentId:governanceId('CON'),user:G.user||'زائر',purpose:'النشر العام',status:action,createdAt:Date.now()});
  governanceChange('تحديث موافقة الخصوصية',G.user||'زائر',action);persist(true);render();toast('تم تحديث الموافقة')
}
function privacyExport(){
  let payload={generatedAt:new Date().toISOString(),user:G.user,memberships:G.memberships,memberData:G.memberData,privacy:{member:G.memberPrivacy,records:G.memberRecordPrivacy,expert:W._private},consents:G.governance.consents.filter(x=>x.user===G.user)};
  downloadBlob('EIM_personal_data.json',JSON.stringify(payload,null,2),'application/json');governanceChange('تصدير بيانات شخصي',G.user||'زائر','JSON');persist(true)
}
function integrationToggle(id){
  if(!governanceIsAdmin())return toast('هذه العملية متاحة لمدير المنصة فقط');
  let x=G.governance.integrations.find(z=>z.integrationId===id);if(!x)return;
  x.status=x.status==='متصل'?'موقوف':'متصل';x.updatedAt=Date.now();governanceChange('تغيير حالة تكامل',id,x.status,'عالي');persist(true);render()
}
function integrationSync(id){
  if(!governanceIsAdmin())return toast('هذه العملية متاحة لمدير المنصة فقط');
  let x=G.governance.integrations.find(z=>z.integrationId===id);if(!x||x.status!=='متصل')return toast('يجب تفعيل التكامل أولًا');
  let run={runId:governanceId('SYNC'),integrationId:id,status:'ناجح',records:Math.floor(Math.random()*40)+1,startedAt:Date.now(),finishedAt:Date.now()+500};
  G.governance.syncRuns.unshift(run);x.lastSync=new Date().toISOString();governanceChange('مزامنة يدوية',id,`${run.records} سجل`);persist(true);render();toast('اكتملت المزامنة التجريبية')
}
function governanceHead(title,desc,actions=''){return pagehead({ctx:'الحوكمة المؤسسية',title,desc},actions)}
function rGovernanceCenter(){
  migrateGovernance();let g=G.governance,high=g.permissions.filter(x=>x.risk==='مرتفع').length,connected=g.integrations.filter(x=>x.status==='متصل').length;
  return governanceHead('مركز الحوكمة والامتثال','نقطة قيادة موحدة للسياسات والأدوار والخصوصية والتدقيق والتكاملات دون تكرار سجلاتها الأصلية.')+`
  <section class="admin-command-hero"><div><span class="kick">GOVERNANCE CONTROL</span><h2>حوكمة مبنية على الدور والدليل</h2><p>كل قرار حساس مرتبط بصلاحية وموافقة وسجل تدقيق، مع فصل واضح بين مالك البيانات والمراجع والمشغل.</p></div><div class="admin-health"><b>${high}</b><small>صلاحيات مرتفعة الحساسية</small></div></section>
  <div class="grid c4">${securityMetric('الأدوار',g.roles.length,'blue')}${securityMetric('الصلاحيات',g.permissions.length,'gold')}${securityMetric('التكاملات المتصلة',connected,'green')}${securityMetric('أحداث الحوكمة',g.changes.length,'violet')}</div>
  <div class="governance-map mt">
    <button class="card quick" onclick="go(106)"><b>مصفوفة الأدوار والصلاحيات</b><small>RBAC، فصل الواجبات، التفويض والمراجعة</small></button>
    <button class="card quick" onclick="go(107)"><b>الخصوصية والموافقات</b><small>إتاحة الحقول، الموافقات، التصدير والاحتفاظ</small></button>
    <button class="card quick" onclick="go(108)"><b>التكاملات وتبادل البيانات</b><small>السجل، الاتجاه، المالك، الحالة والمزامنة</small></button>
    <button class="card quick" onclick="go(95)"><b>المشغلون والتفويض</b><small>تعيين المشغلين وكشف تعارض الصلاحيات</small></button>
    <button class="card quick" onclick="go(96)"><b>سجل التدقيق الموحد</b><small>الأحداث والمخاطر والتتبع والتصدير</small></button>
    <button class="card quick" onclick="go(98)"><b>السياسات وإدارة التغيير</b><small>الإصدارات والسريان والمراجعة والاعتماد</small></button>
  </div>
  <div class="grid c2 mt"><div class="card panel"><h3>مبادئ التحكم</h3>${['أقل صلاحية لازمة','فصل الصانع عن المراجع','تقييد البيانات حسب الغرض','أثر تدقيق غير قابل للمحو','مراجعة دورية للوصول','تعطيل آمن للتكاملات'].map(x=>`<div class="security-row"><b>${x}</b><span class="tagb green">مطبق في النموذج</span></div>`).join('')}</div>
  <div class="card panel"><h3>آخر تغييرات الحوكمة</h3>${g.changes.slice(0,6).map(x=>`<div class="security-row"><div><b>${esc(x.action)}</b><small>${esc(x.actor)} · ${new Date(x.at).toLocaleString('ar')}</small></div><span class="tagb ${x.risk==='عالي'?'amber':'gray'}">${esc(x.ref)}</span></div>`).join('')||'<div class="empty">لا توجد تغييرات مسجلة بعد.</div>'}</div></div>`}
function rRolePermissionMatrix(){
  migrateGovernance();let g=G.governance,roles=g.roles.map(x=>x.name);
  return governanceHead('مصفوفة الأدوار والصلاحيات','صلاحيات معيارية قابلة للمراجعة؛ التعديل الإداري يولد حدث تدقيق ولا يحذف السجل السابق.',`<button class="btn ghost sm" onclick="go(95)">المشغلون والتفويض</button>`)+`
  <div class="card panel"><div class="tablewrap"><table class="tbl permission-matrix"><thead><tr><th>الصلاحية</th>${roles.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${g.permissions.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.permissionId)} · ${esc(p.domain)}</small></td>${roles.map(role=>`<td><button class="perm-toggle ${roleHas(role,p.permissionId)?'on':''}" title="${esc(role+' — '+p.name)}" onclick="permissionToggle('${enc(role)}','${p.permissionId}')">${roleHas(role,p.permissionId)?'✓':'—'}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div></div>
  <div class="note mt">الصلاحيات الحساسة لا تُمنح عبر العضوية وحدها؛ يلزم تعيين إداري، وتُراجع دوريًا، وتظهر ضمن سجل التدقيق.</div>`}
function rPrivacyCenter(){
  migrateGovernance();let s=privacyStats(),cons=G.governance.consents.find(x=>x.user===G.user&&x.purpose==='النشر العام');
  return governanceHead('مركز الخصوصية والموافقات','تحكم العضو في إتاحة كل بيان، ومعرفة أثر الإعدادات، وتصدير بياناته ومراجعة موافقاته.',`<button class="btn ghost sm" onclick="privacyExport()">تصدير بياناتي</button>`)+`
  <div class="grid c2"><div class="privacy-score"><b>${s.score}%</b><span>من البيانات المصنفة متاح للعرض</span><small>${s.public} ظاهر · ${s.hidden} مخفي</small></div>
  <div class="card panel"><h3>موافقة النشر العام</h3><p>تتحكم هذه الموافقة في إنشاء الملف العام، بينما تبقى إعدادات الإخفاء لكل حقل هي المرجع الأعلى.</p><div class="statusband ${cons?.status==='موافق'?'success':'warning'}">${cons?.status==='موافق'?'الموافقة فعالة':'لا توجد موافقة فعالة للنشر العام'}</div><div class="table-actions mt"><button class="btn success" onclick="privacyConsent('موافق')">نعم، أوافق</button><button class="btn danger" onclick="privacyConsent('مسحوبة')">سحب الموافقة</button></div></div></div>
  <div class="grid c2 mt"><div class="card panel"><h3>ضوابط الإتاحة</h3>${G.governance.privacyPolicies.map(x=>`<div class="security-row"><div><b>${esc(x.name)}</b><small>${esc(x.scope)} · الاحتفاظ: ${esc(x.retention)}</small></div><span class="tagb green">${esc(x.status)}</span></div>`).join('')}</div>
  <div class="card panel"><h3>حقوق صاحب البيانات</h3>${[['الاطلاع والتصدير','تنزيل نسخة منظمة من البيانات والموافقات'],['التصحيح','تعديل البيانات من شاشة العضوية المصدر'],['تقييد الإتاحة','إخفاء كل حقل بصورة مستقلة'],['سحب الموافقة','إيقاف النشر دون حذف السجل المهني'],['الاعتراض أو الشكوى','فتح طلب مراجعة موثق']].map(x=>`<div class="security-row"><div><b>${x[0]}</b><small>${x[1]}</small></div><span>←</span></div>`).join('')}</div></div>
  <div class="note mt">لتغيير إتاحة حقل بعينه، افتح «بيانات العضوية» أو «وثائقي وأدلتي». تُستعاد القيم والإعدادات عند الرجوع للشاشة السابقة.</div>`}
function rIntegrationsRegistry(){
  migrateGovernance();let g=G.governance;
  return governanceHead('سجل التكاملات وتبادل البيانات','تعريف كل اتصال ومالكه واتجاهه وبياناته وحالته وسجل مزامناته قبل التنفيذ الخلفي الفعلي.')+`
  <div class="grid c4">${securityMetric('التكاملات',g.integrations.length,'blue')}${securityMetric('متصلة',g.integrations.filter(x=>x.status==='متصل').length,'green')}${securityMetric('موقوفة أو غير متصلة',g.integrations.filter(x=>x.status!=='متصل').length,'amber')}${securityMetric('عمليات المزامنة',g.syncRuns.length,'gold')}</div>
  <div class="grid c2 mt">${g.integrations.map(x=>`<div class="integration-card"><div class="integration-logo">${esc(x.category.slice(0,2))}</div><div><b>${esc(x.name)}</b><small>${esc(x.integrationId)} · ${esc(x.direction)} · المالك: ${esc(x.owner)}</small><small>البيانات: ${esc((x.data||[]).join('، '))}</small><small>آخر مزامنة: ${esc(x.lastSync?new Date(x.lastSync).toLocaleString('ar'):'لا توجد')}</small></div><div><span class="tagb ${x.status==='متصل'?'green':'gray'}">${esc(x.status)}</span><div class="table-actions mt"><button class="btn xs ghost" onclick="integrationToggle('${x.integrationId}')">${x.status==='متصل'?'إيقاف':'تفعيل'}</button><button class="btn xs soft" onclick="integrationSync('${x.integrationId}')">مزامنة</button></div></div></div>`).join('')}</div>
  <div class="card panel mt"><h3>سجل المزامنة</h3><div class="tablewrap"><table class="tbl"><thead><tr><th>المرجع</th><th>التكامل</th><th>البداية</th><th>السجلات</th><th>الحالة</th></tr></thead><tbody>${g.syncRuns.slice(0,20).map(x=>`<tr><td>${esc(x.runId)}</td><td>${esc(x.integrationId)}</td><td>${new Date(x.startedAt).toLocaleString('ar')}</td><td>${x.records}</td><td><span class="tagb green">${esc(x.status)}</span></td></tr>`).join('')||'<tr><td colspan="5">لا توجد عمليات مزامنة بعد.</td></tr>'}</tbody></table></div></div>
  <div class="note mt">هذه الواجهة تثبت عقد التكامل والحوكمة. الاتصال الحقيقي بمزود الهوية أو الدفع أو البريد يتم في المرحلة الخلفية باستخدام مفاتيح آمنة وسجلات تشغيلية.</div>`}
